// Improved application with enhanced security, error handling, and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"]
    }
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: "same-site" },
  dnsPrefetchControl: { allow: false },
  frameguard: { action: "deny" },
  hidePoweredBy: true,
  hsts: { maxAge: 31536000, includeSubDomains: true },
  ieNoOpen: true,
  noSniff: true,
  originAgentCluster: true,
  permittedCrossDomainPolicies: { permittedPolicies: "none" },
  referrerPolicy: { policy: "strict-origin-when-cross-origin" },
  xssFilter: true
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req) => req.ip,
  handler: (req, res) => {
    res.status(429).json({ error: 'Too many requests' });
  }
});

app.use(limiter);

// Body parsing middleware
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Custom error handling middleware
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

// Request validation middleware
const validateInput = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    throw new AppError('Validation failed: ' + errors.array().map(e => e.msg).join(', '), 400);
  }
  next();
};

// Error handling middleware
const globalErrorHandler = (err, req, res, next) => {
  // Log error for debugging (in production use a logging service)
  console.error('Error:', err.message, err.stack);

  // Set default status code
  const statusCode = err.statusCode || 500;

  // In production, hide detailed error messages
  const message = process.env.NODE_ENV === 'production' 
    ? (err.isOperational ? 'An error occurred' : 'Internal server error')
    : err.message;

  res.status(statusCode).json({
    error: {
      message: message,
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
      ...(process.env.NODE_ENV !== 'production' && { type: err.constructor.name })
    },
    timestamp: new Date().toISOString(),
    path: req.path
  });
};

// Health check endpoint (no validation needed)
app.get('/health', (req, res) => {
  res.status(200).json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Users endpoint with validation
app.get('/users', [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer')
    .toInt(),
  validateInput
], (req, res, next) => {
  try {
    const { limit, offset } = req.query;

    // Simulated database query with pagination
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      // In a real application, this would come from a database
    ];

    const paginatedUsers = allUsers.slice(offset || 0, (limit ? (offset || 0) + limit : undefined));

    res.status(200).json({
      data: paginatedUsers,
      total: allUsers.length,
      limit: limit || allUsers.length,
      offset: offset || 0
    });
  } catch (error) {
    next(error);
  }
});

app.get('/users/:id', [
  param('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer')
    .toInt(),
  validateInput
], (req, res, next) => {
  try {
    const userId = req.params.id;

    // Simulated user lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      throw new AppError(`User with ID ${userId} not found`, 404);
    }

    // In real application, we might clean the user data before sending
    const safeUser = {
      id: user.id,
      name: user.name,
      email: user.email
    };

    res.status(200).json({ data: safeUser });
  } catch (error) {
    next(error);
  }
});

// Handle 404 routes
app.use((req, res, next) => {
  next(new AppError(`Route ${req.method} ${req.path} not found`, 404));
});

// Global error handler (must be last)
app.use(globalErrorHandler);

// Start server
const PORT = process.env.PORT || 3000;

// Graceful shutdown handler
const shutdownHandler = () => {
  console.log('Server shutting down gracefully...');
  process.exit(0);
};

process.on('SIGTERM', shutdownHandler);
process.on('SIGINT', shutdownHandler);

// Error handling for server startup
try {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
} catch (error) {
  console.error('Failed to start server:', error.message);
  process.exit(1);
}

module.exports = app;

