const express = require('express');
const app = express();
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const crypto = require('crypto');

// Security middleware
app.use(helmet());
app.use(express.json());

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Custom error handler middleware
const handleError = (err, req, res, next) => {
  console.error('Error:', err.message);

  // Don't leak stack traces or internal details to clients
  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'production' ? 'Internal Server Error' : message
  });
};

// Input validation utility
const validateId = (id) => {
  // Ensure ID is a positive integer
  const parsedId = parseInt(id, 10);
  return !isNaN(parsedId) && parsedId > 0 && parsedId <= 1000000;
};

// Health check endpoint
app.get('/health', (req, res, next) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
  try {
    const { id } = req.query;

    // Validate id parameter if provided
    if (id !== undefined && !validateId(id)) {
      return res.status(400).json({
        error: 'Invalid ID parameter. ID must be a positive integer.'
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // If id query parameter is provided, filter users
    if (id !== undefined) {
      const userId = parseInt(id, 10);
      const user = users.find(u => u.id === userId);
      if (!user) {
        return res.status(404).json({
          error: 'User not found'
        });
      }
      return res.json(user);
    }

    res.json(users);
  } catch (error) {
    next(error);
  }
});

// Search endpoint with input sanitization
app.get('/search', (req, res, next) => {
  try {
    const { q } = req.query;

    // Validate and sanitize search query
    if (!q || typeof q !== 'string' || q.trim().length === 0) {
      return res.status(400).json({
        error: 'Search query is required'
      });
    }

    // Sanitize input to prevent XSS
    const sanitizedQuery = q
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#x27;')
      .replace(/\//g, '&#x2f;');

    // Simulate search results
    const results = [
      { id: 1, title: `Results for: ${sanitizedQuery}`, content: 'Sample content 1' },
      { id: 2, title: `More results for: ${sanitizedQuery}`, content: 'Sample content 2' }
    ];

    res.json({ query: sanitizedQuery, results });
  } catch (error) {
    next(error);
  }
});

// API key generation endpoint with validation
app.post('/api/key', (req, res, next) => {
  try {
    const { userId } = req.body;

    // Validate userId
    if (!userId) {
      return res.status(400).json({
        error: 'User ID is required'
      });
    }

    if (!validateId(userId)) {
      return res.status(400).json({
        error: 'Invalid User ID. Must be a positive integer.'
      });
    }

    // Generate API key
    const apiKey = crypto.randomBytes(32).toString('hex');

    res.json({ 
      apiKey: apiKey, 
      userId: userId,
      message: 'API key generated successfully'
    });
  } catch (error) {
    next(error);
  }
});

// Error handling middleware (must be last)
app.use((err, req, res, next) => {
  handleError(err, req, res, next);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

