        const maxDepth = 10;
        let depth = 0;
        let inString = false;
        let escape = false;

        for (let i = 0; i < rawJson.length; i++) {
          const char = rawJson[i];

          if (escape) {
            escape = false;
            continue;
          }

          if (char === '\\') {
            escape = true;
            continue;
          }

          if (char === '"') {
            inString = !inString;
            continue;
          }

          if (!inString && (char === '{' || char === '[')) {
            depth++;
            if (depth > maxDepth) {
              throw new Error('JSON payload exceeds maximum depth');
            }
          }
        }

        JSON.parse(buf);
      }
    } catch (e) {
      throw new Error('Invalid JSON payload');
    }
  }
