  if (!(err instanceof Error)) {
    // Handle cases where a non-Error object was thrown
    err = new Error(err || 'An unexpected error occurred');
  }

  console.error(`[${new Date().toISOString()}] Error:`, {
    message: err.message,
    name: err.name || 'Error',
    path: req.path,
    method: req.method,
    ip: req.ip
  });

