  if (process.env.NODE_ENV !== 'development') {
    // Check for known security-related errors
    if (err.message.includes('prototype') || 
        err.message.includes('exceeds') || 
        err.message.includes('Invalid JSON')) {
      return err.message; // Allow specific security-related messages
    }
    return 'An internal error occurred. Please try again later.';
  }

  // Return full message in development
  return err.message || 'An unexpected error occurred';
}

// ─────────────────────────────────────────────────────────────────────────────
// Graceful Shutdown
// ─────────────────────────────────────────────────────────────────────────────

const server = app.listen(3000, () => {
  console.log(`Server running on port 3000 in ${process.env.NODE_ENV || 'development'} mode`);
});

// Close server on SIGTERM/SIGINT
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Closing server...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Closing server...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

