  const partsB64 = CLERK_PUBLISHABLE_KEY ? CLERK_PUBLISHABLE_KEY.split("_")[2] ?? "" : "";
  let frontendHost = "";
  if (partsB64) {
    try {
      frontendHost = Buffer.from(partsB64, "base64").toString("utf8").replace(/\$$/, "");
    } catch {
      /* leave empty */
    }
  }
  if (frontendHost) {
    hosts.push(
      await probeOne(
        "frontend-api",
        frontendHost,
        `https://${frontendHost}/.well-known/jwks.json`,
      ),
    );
